const data = $getWorkflowStaticData("global");
const now = Date.now();
if (data.lastFailureEmail && now - data.lastFailureEmail < 3600000) {
  return [];
}
data.lastFailureEmail = now;
return $input.all();

const MODE = "alert";
const j = $input.first().json;
const JOB = j.job || "reminders";
const TEAL = "#00838F";
const NAVY = "#06324F";
const LABELS = { reminders: "Evening-before reminders", changes: "Schedule changes", reconcile: "Delivery check" };
const REASONS = {
unassigned: "No caregiver is assigned to this visit",
inactive_caregiver: "The assigned caregiver is not active",
no_phone: "The caregiver has no phone number on file",
invalid_phone: "The caregiver's phone number is not a valid mobile number",
undeliverable: "Twilio cannot deliver to this caregiver (for example, they replied STOP)",
undelivered: "The text was not delivered",
send_outcome_unknown: "The text may or may not have been sent. Check before resending",
send_failed_repeatedly: "Sending to this caregiver has failed repeatedly",
stale_pending: "A text was started but never confirmed",
caregiver_lookup_failed: "A caregiver who was texted earlier could not be looked up",
};
const ALERTS = {
needs_attention: "Something needs a person to look at it (see Needs review).",
send_failures: "One or more texts failed to send.",
send_outcome_unknown: "The outcome of one or more texts is unknown.",
no_visits_found: "No visits were found for the day.",
run_failed: "The run stopped with an error.",
};
const esc = (v) => String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const c = j.counts || {};
const test = j.mode === "test";
const dry = j.dryRun === true;
const label = LABELS[JOB] || JOB;
const when = new Date().toLocaleString("en-CA", { timeZone: "America/Winnipeg", dateStyle: "medium", timeStyle: "short" });
const dateOf = (opts) => new Date(j.serviceDate + "T12:00:00Z").toLocaleDateString("en-CA", Object.assign({ timeZone: "UTC" }, opts));
const day = j.serviceDate ? dateOf({ weekday: "long", year: "numeric", month: "long", day: "numeric" }) : "";
const shortDay = j.serviceDate ? dateOf({ month: "short", day: "numeric" }) : "";
const alerts = j.alerts || [];
const exceptions = j.exceptions || [];
const warnings = j.warnings || [];
const plural = (n, w) => n + " " + w + (n === 1 ? "" : "s");
const digest = MODE === "digest";
const headline = JOB === "reconcile"
? plural(c.checked || 0, "text") + " checked: " + (c.delivered || 0) + " delivered, " + (c.undelivered || 0) + " not delivered, " + (c.inFlight || 0) + " still in transit."
: dry
? "Dry run for " + day + ": " + plural(c.planned || 0, "text") + " would be sent. Nothing was sent."
: label + " for " + day + ": " + plural(c.sent || 0, "text") + " sent, " + (c.failed || 0) + " failed.";
const modeNote = test
? "Every text goes to the owner's phone only. No caregiver is texted."
: "Texts go to caregivers.";
const runText = dry ? "Dry run (nothing sent)" : "Real send";
const rows = JOB === "reconcile"
? [["Messages checked", c.checked], ["Delivered", c.delivered], ["Not delivered", c.undelivered], ["Still in transit", c.inFlight], ["Not found at Twilio", c.notFound]]
: [
["Visits for the day", c.visits + (c.cancelledVisits ? " (" + c.cancelledVisits + " cancelled)" : "")],
["Caregivers on the schedule", c.caregivers],
["Texts planned", c.planned],
["Texts sent", c.sent],
["Failed", c.failed],
["Already texted earlier", c.skippedAlreadySent],
["Held back by the test limit", c.skippedTestLimit],
["Caregivers with no visits", c.skippedNoVisits],
["Unchanged since last text", c.skippedUnchanged],
].filter((r, i) => r[1] !== undefined && (i < 5 || Number(r[1]) > 0));
const td = "padding:6px 10px;border-bottom:1px solid #e5e7eb;font-size:14px;";
const tableRows = rows.map((r) => "<tr><td style='" + td + "color:#4b5563;'>" + esc(r[0]) + "</td><td style='" + td + "text-align:right;font-weight:600;color:" + NAVY + ";'>" + esc(r[1]) + "</td></tr>").join("");
const excHtml = exceptions.length
? "<ul style='margin:6px 0 0 18px;padding:0;font-size:14px;color:#111827;'>" + exceptions.map((e) => {
const ids = (e.visitIds || []).length ? " Visit" + (e.visitIds.length > 1 ? "s" : "") + " " + e.visitIds.map(esc).join(", ") + "." : "";
const who = e.caregiverUid ? " Caregiver " + esc(e.caregiverUid) + "." : "";
const det = e.detail ? " (" + esc(e.detail) + ")" : "";
return "<li style='margin:4px 0;'>" + esc(REASONS[e.reason] || e.reason) + det + "." + who + ids + "</li>";
}).join("") + "</ul>"
: "<p style='margin:6px 0 0;font-size:14px;color:#4b5563;'>Nothing to review.</p>";
const warnHtml = warnings.length
? "<ul style='margin:6px 0 0 18px;padding:0;font-size:13px;color:#4b5563;'>" + warnings.map((w) => "<li style='margin:3px 0;'>" + esc(w) + "</li>").join("") + "</ul>"
: "";
const whyHtml = alerts.length
? "<ul style='margin:6px 0 0 18px;padding:0;font-size:14px;color:#111827;'>" + alerts.map((a) => "<li style='margin:3px 0;'>" + esc(ALERTS[a] || a) + "</li>").join("") + "</ul>"
: "";
const h = (t) => "<h3 style='margin:20px 0 0;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:" + TEAL + ";'>" + t + "</h3>";
const title = digest ? "Shadow week: daily dry run" : "Needs review: " + label;
const compare = digest
? "<p style='margin:12px 0 0;font-size:14px;line-height:1.5;color:#111827;'>Compare with the old workflow: it should have texted about <strong>" + esc(c.planned) + "</strong> caregivers for this date. Any difference needs an explanation.</p>"
: "";
const html = "<div style='font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;'>"
+ "<div style='background:" + TEAL + ";color:#ffffff;padding:14px 18px;border-radius:6px 6px 0 0;'>"
+ "<div style='font-size:12px;letter-spacing:.06em;text-transform:uppercase;opacity:.9;'>Right at Home Winnipeg &middot; shift reminders</div>"
+ "<div style='font-size:18px;font-weight:600;margin-top:2px;'>" + esc(title) + "</div></div>"
+ "<div style='border:1px solid #e5e7eb;border-top:0;padding:16px 18px;border-radius:0 0 6px 6px;'>"
+ "<p style='margin:0;font-size:15px;line-height:1.5;color:" + NAVY + ";'>" + esc(headline) + "</p>"
+ "<p style='margin:10px 0 0;font-size:13px;color:#4b5563;'><strong>" + (test ? "TEST MODE" : "LIVE") + "</strong>: " + esc(modeNote) + " &middot; " + esc(runText) + "</p>"
+ compare
+ (alerts.length ? h("Why you are getting this") + whyHtml : "")
+ h("Needs review") + excHtml
+ h("Summary") + "<table style='width:100%;border-collapse:collapse;margin-top:6px;'>" + tableRows + "</table>"
+ (warnings.length ? h("Notes") + warnHtml : "")
+ "<p style='margin:22px 0 0;font-size:12px;color:#6b7280;line-height:1.5;'>Run time: " + esc(when) + " (Winnipeg). Workflow: " + esc($workflow.name) + ", execution " + esc($execution.id) + ".<br>This email contains counts and IDs only: no names, phone numbers or message text. For detail, open Coolify, then alayacare-reminders, then Logs.</p>"
+ "</div></div>";
const subject = digest
? "[RAH Reminders] Shadow week" + (shortDay ? " " + shortDay : "") + ": " + plural(c.planned || 0, "text") + " planned"
: "[RAH Reminders] Needs review: " + label + (shortDay ? " for " + shortDay : "") + (test ? " (TEST)" : "");
return [{ json: { subject, html } }];

const j = $input.first().json;
const LABEL = "Schedule changes (20:00)";
const NAVY = "#06324F";
const esc = (v) => String(v).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const detail = typeof j.error === "string" ? j.error : (j.error && j.error.message ? j.error.message : "No detail was returned (the service may not have responded).");
const when = new Date().toLocaleString("en-CA", { timeZone: "America/Winnipeg", dateStyle: "medium", timeStyle: "short" });
const alerts = j.alerts || [];
const li = (t) => "<li style='margin:4px 0;'>" + t + "</li>";
const h = (t) => "<h3 style='margin:20px 0 0;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:#b91c1c;'>" + t + "</h3>";
const html = "<div style='font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#111827;'>"
+ "<div style='background:#b91c1c;color:#ffffff;padding:14px 18px;border-radius:6px 6px 0 0;'>"
+ "<div style='font-size:12px;letter-spacing:.06em;text-transform:uppercase;opacity:.9;'>Right at Home Winnipeg &middot; shift reminders</div>"
+ "<div style='font-size:18px;font-weight:600;margin-top:2px;'>Failed: " + esc(LABEL) + " did not run</div></div>"
+ "<div style='border:1px solid #e5e7eb;border-top:0;padding:16px 18px;border-radius:0 0 6px 6px;'>"
+ "<p style='margin:0;font-size:15px;line-height:1.5;color:" + NAVY + ";'>The reminders service did not return a successful result at " + esc(when) + " (Winnipeg). Some texts may not have been sent.</p>"
+ h("What the service said") + "<p style='margin:6px 0 0;font-size:14px;color:#111827;'>" + esc(detail) + "</p>"
+ (alerts.length ? "<p style='margin:6px 0 0;font-size:13px;color:#4b5563;'>Alerts: " + esc(alerts.join(", ")) + "</p>" : "")
+ h("What to do")
+ "<ol style='margin:6px 0 0 18px;padding:0;font-size:14px;'>"
+ li("Open Coolify, then alayacare-reminders, then Logs, and read the last few lines.")
+ li("Do not run the job again until you know why it stopped. Texts already sent are recorded and are never repeated, so it is safe to wait.")
+ li("You will get at most one of these emails per hour.") + "</ol>"
+ "<p style='margin:22px 0 0;font-size:12px;color:#6b7280;line-height:1.5;'>Workflow: " + esc($workflow.name) + ", execution " + esc($execution.id) + ". This email contains no names, phone numbers or message text.</p>"
+ "</div></div>";
const subject = "[RAH Reminders] FAILED: " + LABEL + " did not run";
return [{ json: { subject, html } }];
